package main

import "sort"

type Instruction struct {
	Op   string
	A, B int64
	Position
	Callee *Declaration
}
type BasicBlock struct {
	First, Last int
	Successors  []int
}
type Unit struct {
	Name                string
	Function            *Declaration
	Code                []Instruction
	Start, Slots, Stack int
	Blocks              []BasicBlock
}
type LoopLabels struct{ Break, Continue int }
type Generator struct {
	Unit   *Unit
	Labels []int
	Loops  []LoopLabels
}

func jump(op string) bool        { return op == "JUMP" || op == "JUMPF" || op == "JUMPT" }
func conditional(op string) bool { return op == "JUMPF" || op == "JUMPT" }
func transfer(op string) bool    { return op == "JUMP" || op == "RET" || op == "RETV" || op == "HALT" }
func (g *Generator) emit(op string, a, b int64, pos Position, callee *Declaration) {
	g.Unit.Code = append(g.Unit.Code, Instruction{op, a, b, pos, callee})
}
func (g *Generator) label() int {
	id := len(g.Labels)
	g.Labels = append(g.Labels, -1)
	return id
}
func (g *Generator) place(label int) { g.Labels[label] = len(g.Unit.Code) }
func (g *Generator) patch() {
	for i := range g.Unit.Code {
		if jump(g.Unit.Code[i].Op) {
			g.Unit.Code[i].A = int64(g.Labels[int(g.Unit.Code[i].A)])
		}
	}
}
func (g *Generator) to(op string, label int, pos Position) { g.emit(op, int64(label), 0, pos, nil) }
func (g *Generator) expression(e *Expr) {
	pos := e.position()
	switch e.Kind {
	case "integer", "boolean":
		g.emit("PUSH", e.Value, 0, pos, nil)
	case "read":
		g.emit("READ", 0, 0, pos, nil)
	case "variable":
		symbol := e.Referent
		op := "LOADL"
		address := symbol.Slot
		if symbol.Kind == "global" {
			op = "LOADG"
			address = symbol.Address
		}
		g.emit(op, int64(address), 0, pos, nil)
	case "array":
		g.expression(e.Children[0])
		g.emit("LOADA", int64(e.Referent.Address), int64(e.Referent.Size), pos, nil)
	case "call":
		for _, argument := range e.Children {
			g.expression(argument)
		}
		g.emit("CALL", 0, int64(len(e.Children)), pos, e.Referent.Declaration)
	case "unary":
		g.expression(e.Children[0])
		op := "NEG"
		if e.Token.Spelling == "!" {
			op = "NOT"
		}
		g.emit(op, 0, 0, pos, nil)
	case "binary":
		op := e.Token.Spelling
		if op == "&&" || op == "||" {
			first, last := g.label(), g.label()
			g.expression(e.Children[0])
			branch, value := "JUMPF", int64(0)
			if op == "||" {
				branch = "JUMPT"
				value = 1
			}
			g.to(branch, first, pos)
			g.expression(e.Children[1])
			g.to("JUMP", last, pos)
			g.place(first)
			g.emit("PUSH", value, 0, pos, nil)
			g.place(last)
		} else {
			g.expression(e.Children[0])
			g.expression(e.Children[1])
			instruction := map[string]string{"+": "ADD", "-": "SUB", "*": "MUL", "/": "DIV", "%": "MOD", "<": "LT", "<=": "LE", ">": "GT", ">=": "GE", "==": "EQ", "!=": "NE"}[op]
			g.emit(instruction, 0, 0, pos, nil)
		}
	}
}
func (g *Generator) statement(s *Statement) {
	if s == nil {
		return
	}
	pos := s.Token.Position
	switch s.Kind {
	case "declaration":
		d := s.Declaration
		if d.Initializer == nil {
			g.emit("PUSH", 0, 0, d.Name.Position, nil)
		} else {
			g.expression(d.Initializer)
		}
		g.emit("STOREL", int64(d.Symbol.Slot), 0, d.Name.Position, nil)
	case "assignment":
		symbol := s.Referent
		if s.Index != nil {
			g.expression(s.Index)
			g.expression(s.Expr)
			g.emit("STOREA", int64(symbol.Address), int64(symbol.Size), pos, nil)
		} else {
			g.expression(s.Expr)
			op, address := "STOREL", symbol.Slot
			if symbol.Kind == "global" {
				op = "STOREG"
				address = symbol.Address
			}
			g.emit(op, int64(address), 0, pos, nil)
		}
	case "call":
		g.expression(s.Expr)
		if s.Expr.Type != "void" {
			g.emit("POP", 0, 0, pos, nil)
		}
	case "print":
		for _, e := range s.Expressions {
			g.expression(e)
		}
		g.emit("PRINT", int64(len(s.Expressions)), 0, pos, nil)
	case "return":
		if s.Expr == nil {
			g.emit("RET", 0, 0, pos, nil)
		} else {
			g.expression(s.Expr)
			g.emit("RETV", 0, 0, pos, nil)
		}
	case "block":
		for _, child := range s.Statements {
			g.statement(child)
		}
	case "if":
		other := g.label()
		g.expression(s.Condition)
		g.to("JUMPF", other, pos)
		g.statement(s.Then)
		if s.Else != nil {
			last := g.label()
			g.to("JUMP", last, pos)
			g.place(other)
			g.statement(s.Else)
			g.place(last)
		} else {
			g.place(other)
		}
	case "while":
		first, last := g.label(), g.label()
		g.place(first)
		g.expression(s.Condition)
		g.to("JUMPF", last, pos)
		g.Loops = append(g.Loops, LoopLabels{last, first})
		g.statement(s.Body)
		g.Loops = g.Loops[:len(g.Loops)-1]
		g.to("JUMP", first, pos)
		g.place(last)
	case "for":
		first, update, last := g.label(), g.label(), g.label()
		g.statement(s.Init)
		g.place(first)
		if s.Condition != nil {
			g.expression(s.Condition)
			g.to("JUMPF", last, pos)
		}
		g.Loops = append(g.Loops, LoopLabels{last, update})
		g.statement(s.Body)
		g.Loops = g.Loops[:len(g.Loops)-1]
		g.place(update)
		g.statement(s.Update)
		g.to("JUMP", first, pos)
		g.place(last)
	case "break", "continue":
		loop := g.Loops[len(g.Loops)-1]
		label := loop.Break
		if s.Kind == "continue" {
			label = loop.Continue
		}
		g.to("JUMP", label, pos)
	}
}
func walkStatements(s *Statement, visit func(*Statement)) {
	if s == nil {
		return
	}
	visit(s)
	for _, child := range s.Statements {
		walkStatements(child, visit)
	}
	for _, child := range []*Statement{s.Then, s.Else, s.Body, s.Init, s.Update} {
		walkStatements(child, visit)
	}
}
func generate(program *Program, reachable map[*Symbol]bool) ([]*Unit, int) {
	cells := 0
	for _, d := range program.Globals {
		d.Symbol.Address = cells
		size := 1
		if d.Array {
			size = int(d.Size.Integer)
		}
		cells += size
	}
	init := &Unit{Name: "<init>"}
	units := []*Unit{init}
	g := &Generator{Unit: init}
	for _, d := range program.Globals {
		if d.Initializer != nil {
			g.expression(d.Initializer)
			g.emit("STOREG", int64(d.Symbol.Address), 0, d.Name.Position, nil)
		}
	}
	main := program.Names["main"].Declaration
	g.emit("CALL", 0, 0, main.Name.Position, main)
	g.emit("HALT", 0, 0, main.Name.Position, nil)
	g.patch()
	for _, function := range program.Functions {
		if !reachable[function.Symbol] {
			continue
		}
		slots := []*Symbol{}
		for _, parameter := range function.Parameters {
			slots = append(slots, parameter.Symbol)
		}
		locals := []*Declaration{}
		walkStatements(function.Body, func(s *Statement) {
			if s.Kind == "declaration" {
				locals = append(locals, s.Declaration)
			}
		})
		sort.Slice(locals, func(i, j int) bool { return earlier(locals[i].Name.Position, locals[j].Name.Position) })
		for _, local := range locals {
			slots = append(slots, local.Symbol)
		}
		for i, symbol := range slots {
			symbol.Slot = i
		}
		function.Slots = slots
		unit := &Unit{Name: function.Name.Spelling, Function: function, Slots: len(slots)}
		g = &Generator{Unit: unit}
		g.emit("ENTER", int64(unit.Slots), 0, function.Name.Position, nil)
		g.statement(function.Body)
		if function.Type == "void" {
			g.emit("RET", 0, 0, function.Body.Close.Position, nil)
		}
		g.patch()
		units = append(units, unit)
	}
	return units, cells
}

package main

import (
	"strconv"
	"strings"
)

type Position struct{ Line, Column int }

func earlier(a, b Position) bool  { return a.Line < b.Line || a.Line == b.Line && a.Column < b.Column }
func (p Position) String() string { return strconv.Itoa(p.Line) + ":" + strconv.Itoa(p.Column) }

type Token struct {
	Kind, Spelling string
	Integer        int64
	Position
}
type CompileError struct {
	Kind, Message string
	Position
}

func wordIn(words, value string) bool {
	for _, word := range strings.Fields(words) {
		if word == value {
			return true
		}
	}
	return false
}
func letter(c byte) bool { return c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c == '_' }
func digit(c byte) bool  { return c >= '0' && c <= '9' }
func tokenize(lines []string, firstLine int) ([]Token, *CompileError) {
	source := strings.Join(lines, "\n") + "\n"
	positions := make([]Position, len(source))
	line, column := firstLine, 1
	for i := range source {
		positions[i] = Position{line, column}
		if source[i] == '\n' {
			line++
			column = 1
		} else {
			column++
		}
	}
	tokens := []Token{}
	for i := 0; i < len(source); {
		c := source[i]
		if c == ' ' || c == '\n' {
			i++
			continue
		}
		start := i
		pos := positions[i]
		if strings.HasPrefix(source[i:], "//") {
			for i < len(source) && source[i] != '\n' {
				i++
			}
			continue
		}
		if strings.HasPrefix(source[i:], "/*") {
			end := strings.Index(source[i+2:], "*/")
			if end < 0 {
				return nil, &CompileError{"lexical", "unterminated comment", pos}
			}
			i += end + 4
			continue
		}
		if letter(c) {
			i++
			for i < len(source) && (letter(source[i]) || digit(source[i])) {
				i++
			}
			spelling := source[start:i]
			kind := "identifier"
			if wordIn("int bool void true false if else while for break continue return print read", spelling) {
				kind = spelling
			}
			tokens = append(tokens, Token{Kind: kind, Spelling: spelling, Position: pos})
			continue
		}
		if digit(c) {
			i++
			for i < len(source) && digit(source[i]) {
				i++
			}
			spelling := source[start:i]
			digits := strings.TrimLeft(spelling, "0")
			if len(digits) > 10 || len(digits) == 10 && digits > "2147483647" {
				return nil, &CompileError{"lexical", "integer literal too large", pos}
			}
			value, _ := strconv.ParseInt(spelling, 10, 64)
			tokens = append(tokens, Token{Kind: "integer", Spelling: spelling, Integer: value, Position: pos})
			continue
		}
		if i+1 < len(source) && wordIn("<= >= == != && ||", source[i:i+2]) {
			spelling := source[i : i+2]
			tokens = append(tokens, Token{Kind: spelling, Spelling: spelling, Position: pos})
			i += 2
			continue
		}
		if strings.ContainsRune("+-*/%<>=!(){}[],;", rune(c)) {
			spelling := string(c)
			tokens = append(tokens, Token{Kind: spelling, Spelling: spelling, Position: pos})
			i++
			continue
		}
		return nil, &CompileError{"lexical", "unexpected character '" + string(c) + "'", pos}
	}
	tokens = append(tokens, Token{Kind: "END", Position: Position{firstLine + len(lines) - 1, len(lines[len(lines)-1]) + 1}})
	return tokens, nil
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Source struct {
	Name      string
	FirstLine int
	Lines     []string
}
type Warning struct {
	Position
	Message string
}

var ruleNames = []string{"const-jump", "not-compare", "not-jump", "invert-branch", "thread", "jump-next", "unreachable"}

func reachableFunctions(p *Program) map[*Symbol]bool {
	reachable := map[*Symbol]bool{}
	var visit func(*Symbol)
	visit = func(f *Symbol) {
		if reachable[f] {
			return
		}
		reachable[f] = true
		for callee := range f.Calls {
			visit(callee)
		}
	}
	visit(p.Names["main"])
	return reachable
}
func collectWarnings(p *Program, reachable map[*Symbol]bool) []Warning {
	out := []Warning{}
	for _, symbol := range p.Symbols {
		if symbol.Kind != "function" && symbol.Reads == 0 {
			kind := "variable"
			if symbol.Kind == "parameter" {
				kind = "parameter"
			}
			out = append(out, Warning{symbol.Declaration.Name.Position, "unused " + kind + " '" + symbol.Name + "'"})
		}
	}
	for _, f := range p.Functions {
		if !reachable[f.Symbol] {
			out = append(out, Warning{f.Name.Position, "function '" + f.Name.Spelling + "' is never called"})
		}
		walkStatements(f.Body, func(s *Statement) {
			if s.Kind != "block" {
				return
			}
			for i, child := range s.Statements {
				if !canComplete(child) {
					if i+1 < len(s.Statements) {
						out = append(out, Warning{s.Statements[i+1].Token.Position, "unreachable statement"})
					}
					break
				}
			}
		})
	}
	sort.Slice(out, func(i, j int) bool { return earlier(out[i].Position, out[j].Position) })
	return out
}
func literal(e *Expr) bool { return e.Kind == "integer" || e.Kind == "boolean" }
func inRange(v int64) bool { return v >= -2147483648 && v <= 2147483647 }
func foldedLiteral(e *Expr, value int64) *Expr {
	kind := "integer"
	if e.Type == "bool" {
		kind = "boolean"
	}
	return &Expr{Kind: kind, Type: e.Type, Token: e.Token, Value: value}
}
func constantBinary(op string, a, b int64) (int64, bool) {
	value := int64(0)
	answer := false
	switch op {
	case "+":
		value = a + b
		return value, inRange(value)
	case "-":
		value = a - b
		return value, inRange(value)
	case "*":
		value = a * b
		return value, inRange(value)
	case "/", "%":
		if b == 0 {
			return 0, false
		}
		q := a / b
		if op == "/" {
			return q, inRange(q)
		}
		return a - q*b, true
	case "<":
		answer = a < b
	case "<=":
		answer = a <= b
	case ">":
		answer = a > b
	case ">=":
		answer = a >= b
	case "==":
		answer = a == b
	case "!=":
		answer = a != b
	case "&&":
		answer = a != 0 && b != 0
	case "||":
		answer = a != 0 || b != 0
	}
	if answer {
		value = 1
	}
	return value, true
}
func foldExpression(e *Expr, count *int) *Expr {
	if e == nil {
		return nil
	}
	for i, child := range e.Children {
		e.Children[i] = foldExpression(child, count)
	}
	if e.Kind == "unary" && literal(e.Children[0]) {
		value := e.Children[0].Value
		if e.Token.Spelling == "-" {
			value = -value
			if !inRange(value) {
				return e
			}
		} else {
			if value == 0 {
				value = 1
			} else {
				value = 0
			}
		}
		*count++
		return foldedLiteral(e, value)
	}
	if e.Kind != "binary" {
		return e
	}
	left, right := e.Children[0], e.Children[1]
	op := e.Token.Spelling
	if literal(left) && literal(right) {
		if value, ok := constantBinary(op, left.Value, right.Value); ok {
			*count++
			return foldedLiteral(e, value)
		}
	}
	if literal(left) {
		if op == "&&" && left.Value == 0 || op == "||" && left.Value != 0 {
			*count++
			return foldedLiteral(e, left.Value)
		}
		if op == "&&" && left.Value != 0 || op == "||" && left.Value == 0 || op == "+" && left.Value == 0 || op == "*" && left.Value == 1 {
			*count++
			return right
		}
	}
	if literal(right) && (op == "+" && right.Value == 0 || op == "-" && right.Value == 0 || op == "*" && right.Value == 1 || op == "/" && right.Value == 1 || op == "&&" && right.Value != 0 || op == "||" && right.Value == 0) {
		*count++
		return left
	}
	return e
}
func foldStatement(s *Statement, count *int) *Statement {
	if s == nil {
		return nil
	}
	switch s.Kind {
	case "if":
		s.Condition = foldExpression(s.Condition, count)
		if literal(s.Condition) {
			var replacement *Statement
			if s.Condition.Value != 0 {
				replacement = foldStatement(s.Then, count)
			} else if s.Else != nil {
				replacement = foldStatement(s.Else, count)
			} else {
				replacement = &Statement{Kind: "empty", Token: s.Token}
			}
			*count++
			return replacement
		}
		s.Then = foldStatement(s.Then, count)
		s.Else = foldStatement(s.Else, count)
	case "while":
		s.Condition = foldExpression(s.Condition, count)
		if literal(s.Condition) && s.Condition.Value == 0 {
			*count++
			return &Statement{Kind: "empty", Token: s.Token}
		}
		s.Body = foldStatement(s.Body, count)
	case "for":
		s.Init = foldStatement(s.Init, count)
		s.Condition = foldExpression(s.Condition, count)
		s.Update = foldStatement(s.Update, count)
		s.Body = foldStatement(s.Body, count)
	case "block":
		for i, child := range s.Statements {
			s.Statements[i] = foldStatement(child, count)
		}
	case "declaration":
		s.Declaration.Initializer = foldExpression(s.Declaration.Initializer, count)
	case "assignment":
		s.Index = foldExpression(s.Index, count)
		s.Expr = foldExpression(s.Expr, count)
	case "call", "return":
		s.Expr = foldExpression(s.Expr, count)
	case "print":
		for i, e := range s.Expressions {
			s.Expressions[i] = foldExpression(e, count)
		}
	}
	return s
}
func foldProgram(p *Program, reachable map[*Symbol]bool) int {
	count := 0
	for _, d := range p.Globals {
		d.Initializer = foldExpression(d.Initializer, &count)
	}
	for _, f := range p.Functions {
		if reachable[f.Symbol] {
			f.Body = foldStatement(f.Body, &count)
		}
	}
	return count
}
func inverse(op string) string {
	if op == "JUMPF" {
		return "JUMPT"
	}
	return "JUMPF"
}
func branchTaken(op string, value int64) bool {
	return op == "JUMPF" && value == 0 || op == "JUMPT" && value != 0
}
func deleteInstruction(unit *Unit, index int) {
	unit.Code = append(unit.Code[:index], unit.Code[index+1:]...)
	for i := range unit.Code {
		if jump(unit.Code[i].Op) && unit.Code[i].A > int64(index) {
			unit.Code[i].A--
		}
	}
}
func optimize(unit *Unit) []int {
	counts := make([]int, 7)
	negations := map[string]string{"LT": "GE", "GE": "LT", "LE": "GT", "GT": "LE", "EQ": "NE", "NE": "EQ"}
	for {
		targets := map[int]bool{}
		for _, instruction := range unit.Code {
			if jump(instruction.Op) {
				targets[int(instruction.A)] = true
			}
		}
		applied := false
		for i := 0; i < len(unit.Code); i++ {
			a := unit.Code[i]
			free := i+1 < len(unit.Code) && !targets[i+1]
			var b Instruction
			if i+1 < len(unit.Code) {
				b = unit.Code[i+1]
			}
			rule := -1
			switch {
			case a.Op == "PUSH" && free && conditional(b.Op):
				if branchTaken(b.Op, a.A) {
					unit.Code[i] = Instruction{Op: "JUMP", A: b.A, Position: b.Position}
					deleteInstruction(unit, i+1)
				} else {
					deleteInstruction(unit, i+1)
					deleteInstruction(unit, i)
				}
				rule = 0
			case negations[a.Op] != "" && free && b.Op == "NOT":
				unit.Code[i].Op = negations[a.Op]
				deleteInstruction(unit, i+1)
				rule = 1
			case a.Op == "NOT" && free && conditional(b.Op):
				unit.Code[i] = Instruction{Op: inverse(b.Op), A: b.A, Position: b.Position}
				deleteInstruction(unit, i+1)
				rule = 2
			case conditional(a.Op) && a.A == int64(i+2) && free && b.Op == "JUMP":
				unit.Code[i] = Instruction{Op: inverse(a.Op), A: b.A, Position: a.Position}
				deleteInstruction(unit, i+1)
				rule = 3
			default:
				if jump(a.Op) && int(a.A) < len(unit.Code) {
					t := int(a.A)
					target := unit.Code[t]
					newTarget := -1
					if target.Op == "JUMP" {
						newTarget = int(target.A)
					} else if target.Op == "PUSH" && t+1 < len(unit.Code) && conditional(unit.Code[t+1].Op) {
						next := unit.Code[t+1]
						newTarget = t + 2
						if branchTaken(next.Op, target.A) {
							newTarget = int(next.A)
						}
					}
					if newTarget >= 0 && newTarget != t {
						unit.Code[i].A = int64(newTarget)
						rule = 4
					}
				}
				if rule < 0 && jump(a.Op) && a.A == int64(i+1) {
					if a.Op == "JUMP" {
						deleteInstruction(unit, i)
					} else {
						unit.Code[i] = Instruction{Op: "POP", Position: a.Position}
					}
					rule = 5
				}
				if rule < 0 && transfer(a.Op) && free {
					deleteInstruction(unit, i+1)
					rule = 6
				}
			}
			if rule >= 0 {
				counts[rule]++
				applied = true
				break
			}
		}
		if !applied {
			return counts
		}
	}
}
func arrange(units []*Unit) int {
	start := 0
	starts := map[*Declaration]int{}
	for _, unit := range units {
		unit.Start = start
		starts[unit.Function] = start
		start += len(unit.Code)
	}
	for _, unit := range units {
		for i := range unit.Code {
			if unit.Code[i].Op == "CALL" {
				unit.Code[i].A = int64(starts[unit.Code[i].Callee])
			}
		}
	}
	return start
}
func stackEffect(instruction Instruction) int {
	switch instruction.Op {
	case "PUSH", "LOADG", "LOADL", "READ":
		return 1
	case "POP", "STOREG", "STOREL", "JUMPF", "JUMPT", "RETV", "ADD", "SUB", "MUL", "DIV", "MOD", "LT", "LE", "GT", "GE", "EQ", "NE":
		return -1
	case "STOREA":
		return -2
	case "CALL":
		effect := -int(instruction.B)
		if instruction.Callee.Type != "void" {
			effect++
		}
		return effect
	case "PRINT":
		return -int(instruction.A)
	}
	return 0
}
func analyzeUnit(unit *Unit) {
	n := len(unit.Code)
	leaders := map[int]bool{0: true}
	for i, instruction := range unit.Code {
		if jump(instruction.Op) && int(instruction.A) < n {
			leaders[int(instruction.A)] = true
		}
		if (jump(instruction.Op) || transfer(instruction.Op)) && i+1 < n {
			leaders[i+1] = true
		}
	}
	indices := []int{}
	for i := range leaders {
		indices = append(indices, i)
	}
	sort.Ints(indices)
	blockOf := make([]int, n)
	for k, first := range indices {
		last := n - 1
		if k+1 < len(indices) {
			last = indices[k+1] - 1
		}
		for i := first; i <= last; i++ {
			blockOf[i] = k
		}
		unit.Blocks = append(unit.Blocks, BasicBlock{First: first, Last: last})
	}
	for k, block := range unit.Blocks {
		last := unit.Code[block.Last]
		successors := []int{}
		if last.Op == "JUMP" {
			successors = append(successors, int(last.A))
		} else if conditional(last.Op) {
			successors = append(successors, block.Last+1, int(last.A))
		} else if !transfer(last.Op) {
			successors = append(successors, block.Last+1)
		}
		seen := map[int]bool{}
		for _, index := range successors {
			if index < n && !seen[blockOf[index]] {
				unit.Blocks[k].Successors = append(unit.Blocks[k].Successors, blockOf[index])
				seen[blockOf[index]] = true
			}
		}
	}
	depths := make([]int, n)
	for i := range depths {
		depths[i] = -1
	}
	depths[0] = 0
	queue := []int{0}
	for head := 0; head < len(queue); head++ {
		i := queue[head]
		instruction := unit.Code[i]
		nextDepth := depths[i] + stackEffect(instruction)
		unit.Stack = max(unit.Stack, nextDepth)
		next := []int{}
		if !transfer(instruction.Op) && i+1 < n {
			next = append(next, i+1)
		}
		if jump(instruction.Op) && int(instruction.A) < n {
			next = append(next, int(instruction.A))
		}
		for _, j := range next {
			if depths[j] < 0 {
				depths[j] = nextDepth
				queue = append(queue, j)
			}
		}
	}
}
func recursive(function *Symbol) bool {
	seen := map[*Symbol]bool{}
	var visit func(*Symbol) bool
	visit = func(current *Symbol) bool {
		seen[current] = true
		for callee := range current.Calls {
			if callee == function {
				return true
			}
			if !seen[callee] && visit(callee) {
				return true
			}
		}
		return false
	}
	return visit(function)
}
func spelling(instruction Instruction, start int) string {
	out := instruction.Op
	a := instruction.A
	if jump(instruction.Op) {
		a += int64(start)
	}
	if wordIn("PUSH LOADG STOREG LOADL STOREL LOADA STOREA JUMP JUMPF JUMPT CALL ENTER PRINT", instruction.Op) {
		out += " " + strconv.FormatInt(a, 10)
	}
	if instruction.Op == "LOADA" || instruction.Op == "STOREA" || instruction.Op == "CALL" {
		out += " " + strconv.FormatInt(instruction.B, 10)
	}
	return out
}
func callees(symbol *Symbol) string {
	names := []string{}
	for callee := range symbol.Calls {
		names = append(names, callee.Name)
	}
	sort.Strings(names)
	if len(names) == 0 {
		return "-"
	}
	return strings.Join(names, ",")
}
func listing(p *Program, before, after []*Unit, beforeCount, afterCount int) []string {
	out := []string{}
	if len(p.Globals) == 0 {
		out = append(out, "globals: none")
	} else {
		out = append(out, "globals:")
		for _, d := range p.Globals {
			typ := d.Type
			if d.Array {
				typ = fmt.Sprintf("int[%d]", d.Size.Integer)
			}
			out = append(out, fmt.Sprintf("  %d %s %s", d.Symbol.Address, d.Name.Spelling, typ))
		}
	}
	out = append(out, "functions:")
	for i, unit := range after {
		signature, calls, suffix := "", "main", ""
		if unit.Function != nil {
			f := unit.Function
			parameters := []string{}
			for _, p := range f.Parameters {
				parameters = append(parameters, p.Type)
			}
			signature = " " + f.Type + "(" + strings.Join(parameters, ",") + ")"
			calls = callees(f.Symbol)
			if recursive(f.Symbol) {
				suffix = " recursive"
			}
		}
		out = append(out, fmt.Sprintf("  %s%s address=%d->%d size=%d->%d slots=%d stack=%d blocks=%d calls=%s%s", unit.Name, signature, before[i].Start, unit.Start, len(before[i].Code), len(unit.Code), unit.Slots, unit.Stack, len(unit.Blocks), calls, suffix))
		if unit.Function != nil {
			for slot, symbol := range unit.Function.Slots {
				out = append(out, fmt.Sprintf("    slot %d %s %s", slot, symbol.Name, symbol.Type))
			}
		}
	}
	out = append(out, "references:")
	declarations := append(append([]*Declaration{}, p.Globals...), p.Functions...)
	for _, d := range declarations {
		lines := map[int]bool{}
		for _, position := range d.Symbol.References {
			lines[position.Line] = true
		}
		ordered := []int{}
		for line := range lines {
			ordered = append(ordered, line)
		}
		sort.Ints(ordered)
		used := []string{}
		for _, line := range ordered {
			used = append(used, strconv.Itoa(line))
		}
		value := strings.Join(used, " ")
		if value == "" {
			value = "-"
		}
		out = append(out, fmt.Sprintf("  %s defined %d used %s", d.Name.Spelling, d.Name.Line, value))
	}
	for pass, units := range [][]*Unit{before, after} {
		label, count := "before", beforeCount
		if pass == 1 {
			label = "after"
			count = afterCount
		}
		out = append(out, fmt.Sprintf("%s peephole: %d instructions", label, count))
		for _, unit := range units {
			out = append(out, unit.Name+":")
			for i, instruction := range unit.Code {
				out = append(out, fmt.Sprintf("%5d  %s", unit.Start+i, spelling(instruction, unit.Start)))
			}
		}
	}
	out = append(out, "control flow:")
	for _, unit := range after {
		out = append(out, "  "+unit.Name)
		for k, block := range unit.Blocks {
			line := fmt.Sprintf("    B%d %d-%d", k, unit.Start+block.First, unit.Start+block.Last)
			if len(block.Successors) > 0 {
				names := []string{}
				for _, successor := range block.Successors {
					names = append(names, fmt.Sprintf("B%d", successor))
				}
				line += " -> " + strings.Join(names, " ")
			}
			out = append(out, line)
		}
	}
	return out
}
func sameBehavior(a, b *RunResult) bool {
	if a.Error != b.Error || len(a.Output) != len(b.Output) {
		return false
	}
	for i, line := range a.Output {
		if line != b.Output[i] {
			return false
		}
	}
	return true
}
func sumCounts(counts []int) int {
	sum := 0
	for _, count := range counts {
		sum += count
	}
	return sum
}

type NamedCount struct {
	Name  string
	Count int
}

func sortedCounts(counts map[string]int, positive bool) []NamedCount {
	out := []NamedCount{}
	for name, count := range counts {
		if !positive || count > 0 {
			out = append(out, NamedCount{name, count})
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Count != out[j].Count {
			return out[i].Count > out[j].Count
		}
		return out[i].Name < out[j].Name
	})
	return out
}
func statsLines(units []*Unit, beforeCount, afterCount, folds int, rules []int, run, comparison *RunResult) []string {
	behaviour := "different"
	if sameBehavior(run, comparison) {
		behaviour = "same"
	}
	out := []string{fmt.Sprintf("code: %d -> %d", beforeCount, afterCount), fmt.Sprintf("folds: %d", folds), fmt.Sprintf("peephole: %d", sumCounts(rules))}
	for i, name := range ruleNames {
		out = append(out, fmt.Sprintf("  %s %d", name, rules[i]))
	}
	out = append(out, fmt.Sprintf("executed: %d", run.Executed), fmt.Sprintf("executed before peephole: %d", comparison.Executed), "behaviour: "+behaviour, fmt.Sprintf("max call depth: %d", run.MaximumDepth), fmt.Sprintf("max stack: %d", run.MaximumStack), "opcodes:")
	code := flatten(units)
	opcodes := map[string]int{}
	functions := map[string]int{}
	lineCounts := map[int]int{}
	for _, unit := range units {
		if unit.Function != nil {
			functions[unit.Name] = 0
		}
	}
	for pc, instruction := range code {
		count := run.Counts[pc]
		opcodes[instruction.Op] += count
		if instruction.Unit.Function != nil {
			functions[instruction.Unit.Name] += count
		}
		lineCounts[instruction.Line] += count
	}
	for _, record := range sortedCounts(opcodes, true) {
		out = append(out, fmt.Sprintf("  %s %d", record.Name, record.Count))
	}
	out = append(out, "functions:")
	for _, record := range sortedCounts(functions, false) {
		out = append(out, fmt.Sprintf("  %s calls=%d executed=%d", record.Name, run.Calls[record.Name], record.Count))
	}
	out = append(out, "calls:")
	pairs := [][2]string{}
	for pair, count := range run.Pairs {
		if count > 0 {
			pairs = append(pairs, pair)
		}
	}
	sort.Slice(pairs, func(i, j int) bool {
		a, b := pairs[i], pairs[j]
		if run.Pairs[a] != run.Pairs[b] {
			return run.Pairs[a] > run.Pairs[b]
		}
		if a[0] != b[0] {
			return a[0] < b[0]
		}
		return a[1] < b[1]
	})
	for _, pair := range pairs {
		out = append(out, fmt.Sprintf("  %s -> %s %d", pair[0], pair[1], run.Pairs[pair]))
	}
	positive, negative := []int{}, []int{}
	for line, count := range lineCounts {
		if count > 0 {
			positive = append(positive, line)
		} else {
			negative = append(negative, line)
		}
	}
	sort.Slice(positive, func(i, j int) bool {
		if lineCounts[positive[i]] != lineCounts[positive[j]] {
			return lineCounts[positive[i]] > lineCounts[positive[j]]
		}
		return positive[i] < positive[j]
	})
	sort.Ints(negative)
	out = append(out, "hot lines:")
	for _, line := range positive[:min(5, len(positive))] {
		out = append(out, fmt.Sprintf("  line %d: %d", line, lineCounts[line]))
	}
	out = append(out, fmt.Sprintf("coverage: %d of %d lines", len(positive), len(lineCounts)))
	missing := []string{}
	for _, line := range negative {
		missing = append(missing, strconv.Itoa(line))
	}
	unexecuted := "none"
	if len(missing) > 0 {
		unexecuted = strings.Join(missing, " ")
	}
	out = append(out, "not executed: "+unexecuted, "hot spots:")
	pcs := []int{}
	for pc, count := range run.Counts {
		if count > 0 {
			pcs = append(pcs, pc)
		}
	}
	sort.Slice(pcs, func(i, j int) bool {
		if run.Counts[pcs[i]] != run.Counts[pcs[j]] {
			return run.Counts[pcs[i]] > run.Counts[pcs[j]]
		}
		return pcs[i] < pcs[j]
	})
	for _, pc := range pcs[:min(5, len(pcs))] {
		instruction := code[pc]
		out = append(out, fmt.Sprintf("  pc=%d count=%d %s", pc, run.Counts[pc], spelling(instruction.Instruction, 0)))
	}
	return out
}
func positionDisplay(pos Position, allLines []string) []string {
	return []string{"  " + allLines[pos.Line-1], strings.Repeat(" ", pos.Column+1) + "^"}
}
func runtimeDiagnostics(units []*Unit, run *RunResult, allLines []string) []string {
	code := flatten(units)
	instruction := code[run.FaultPC]
	out := []string{fmt.Sprintf("runtime error %s: %s in %s", instruction.Position, run.Error, instruction.Unit.Name)}
	out = append(out, positionDisplay(instruction.Position, allLines)...)
	count := max(0, len(run.Frames)-1)
	shown := 0
	for i := len(run.Frames) - 1; i >= 1 && shown < 5; i-- {
		caller := code[run.Frames[i].Return-1]
		out = append(out, fmt.Sprintf("  called from %s at %s", caller.Unit.Name, caller.Position))
		shown++
	}
	if count > shown {
		out = append(out, fmt.Sprintf("  ... %d more", count-shown))
	}
	return out
}
func readLines(path string) []string {
	f, err := os.Open(path)
	if err != nil {
		panic(err)
	}
	defer f.Close()
	lines := []string{}
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err = scanner.Err(); err != nil {
		panic(err)
	}
	return lines
}
func sources(lines []string) []Source {
	out := []Source{}
	for i, line := range lines {
		if strings.HasPrefix(line, "#program ") {
			out = append(out, Source{Name: strings.TrimPrefix(line, "#program "), FirstLine: i + 2})
		} else {
			out[len(out)-1].Lines = append(out[len(out)-1].Lines, line)
		}
	}
	return out
}
func inputs() map[string][]int64 {
	out := map[string][]int64{}
	name := ""
	for _, line := range readLines("input/input.txt") {
		if strings.HasPrefix(line, "#input ") {
			name = strings.TrimPrefix(line, "#input ")
			out[name] = []int64{}
		} else {
			for _, word := range strings.Split(line, " ") {
				value, _ := strconv.ParseInt(word, 10, 64)
				out[name] = append(out[name], value)
			}
		}
	}
	return out
}
func writeLines(path string, lines []string) {
	if err := os.WriteFile("output/"+path, []byte(strings.Join(lines, "\n")+"\n"), 0644); err != nil {
		panic(err)
	}
}
func main() {
	allLines := readLines("input/program.src")
	programs := sources(allLines)
	input := inputs()
	listingReport, output, diagnostics, statistics := []string{}, []string{}, []string{}, []string{}
	compiled, runtimeErrors, totalFolds, totalExecuted := 0, 0, 0, 0
	errors := map[string]int{}
	totalRules := make([]int, 7)
	table := [][]string{{"program", "status", "code", "executed", "output"}}
	for _, source := range programs {
		heading := "== program " + source.Name + " =="
		listingReport = append(listingReport, heading)
		output = append(output, heading)
		diagnostics = append(diagnostics, heading)
		statistics = append(statistics, heading)
		tokens, err := tokenize(source.Lines, source.FirstLine)
		var program *Program
		if err == nil {
			program, err = parse(tokens)
		}
		if err == nil {
			err = analyze(program)
		}
		if err != nil {
			errors[err.Kind]++
			listingReport = append(listingReport, "not compiled")
			statistics = append(statistics, "not compiled")
			diagnostics = append(diagnostics, fmt.Sprintf("%s error %s: %s", err.Kind, err.Position, err.Message))
			diagnostics = append(diagnostics, positionDisplay(err.Position, allLines)...)
			diagnostics = append(diagnostics, "status: compile error")
			table = append(table, []string{source.Name, err.Kind + " error", "-", "-", "-"})
			continue
		}
		compiled++
		reachable := reachableFunctions(program)
		warnings := collectWarnings(program, reachable)
		for _, warning := range warnings {
			diagnostics = append(diagnostics, fmt.Sprintf("warning %s: %s", warning.Position, warning.Message))
		}
		folds := foldProgram(program, reachable)
		before, cells := generate(program, reachable)
		beforeCount := arrange(before)
		after := []*Unit{}
		rules := make([]int, 7)
		for _, original := range before {
			unit := &Unit{Name: original.Name, Function: original.Function, Code: append([]Instruction{}, original.Code...), Slots: original.Slots}
			counts := optimize(unit)
			for i, count := range counts {
				rules[i] += count
			}
			analyzeUnit(unit)
			after = append(after, unit)
		}
		afterCount := arrange(after)
		listingReport = append(listingReport, listing(program, before, after, beforeCount, afterCount)...)
		run := execute(after, cells, input[source.Name])
		comparison := execute(before, cells, input[source.Name])
		output = append(output, run.Output...)
		status := "ok"
		if run.Error != "" {
			runtimeErrors++
			status = "runtime error"
			diagnostics = append(diagnostics, runtimeDiagnostics(after, run, allLines)...)
		}
		diagnostics = append(diagnostics, "status: "+status)
		statistics = append(statistics, statsLines(after, beforeCount, afterCount, folds, rules, run, comparison)...)
		totalFolds += folds
		totalExecuted += run.Executed
		for i, count := range rules {
			totalRules[i] += count
		}
		table = append(table, []string{source.Name, status, strconv.Itoa(afterCount), strconv.Itoa(run.Executed), strconv.Itoa(len(run.Output))})
	}
	statistics = append(statistics, "== summary ==", fmt.Sprintf("programs: %d", len(programs)), fmt.Sprintf("compiled: %d", compiled), fmt.Sprintf("compile errors: lexical %d syntax %d semantic %d", errors["lexical"], errors["syntax"], errors["semantic"]), fmt.Sprintf("runtime errors: %d", runtimeErrors), fmt.Sprintf("folds: %d", totalFolds), fmt.Sprintf("peephole: %d", sumCounts(totalRules)))
	for i, name := range ruleNames {
		statistics = append(statistics, fmt.Sprintf("  %s %d", name, totalRules[i]))
	}
	statistics = append(statistics, fmt.Sprintf("executed: %d", totalExecuted))
	widths := make([]int, 5)
	for _, row := range table {
		for i, value := range row {
			widths[i] = max(widths[i], len(value))
		}
	}
	for _, row := range table {
		values := []string{}
		for i, value := range row {
			padding := strings.Repeat(" ", widths[i]-len(value))
			if i < 2 {
				values = append(values, value+padding)
			} else {
				values = append(values, padding+value)
			}
		}
		statistics = append(statistics, "  "+strings.Join(values, "  "))
	}
	if err := os.MkdirAll("output", 0755); err != nil {
		panic(err)
	}
	writeLines("listing.txt", listingReport)
	writeLines("output.txt", output)
	writeLines("diagnostics.txt", diagnostics)
	writeLines("stats.txt", statistics)
}

package main

type Expr struct {
	Kind, Type string
	Token      Token
	Value      int64
	Children   []*Expr
	Referent   *Symbol
}

func (e *Expr) position() Position { return e.Token.Position }

type Declaration struct {
	Type            string
	Name            Token
	Array, Function bool
	Size            Token
	Initializer     *Expr
	Parameters      []*Declaration
	Body            *Statement
	Symbol          *Symbol
	Slots           []*Symbol
}
type Statement struct {
	Kind                           string
	Token, Close                   Token
	Declaration                    *Declaration
	Expr, Index, Condition         *Expr
	Expressions                    []*Expr
	Statements                     []*Statement
	Then, Else, Body, Init, Update *Statement
	Referent                       *Symbol
}
type Program struct {
	Declarations       []*Declaration
	End                Token
	Globals, Functions []*Declaration
	Names              map[string]*Symbol
	Symbols            []*Symbol
}
type Parser struct {
	Tokens []Token
	Index  int
}

func (p *Parser) peek() Token { return p.Tokens[p.Index] }
func (p *Parser) fail() {
	t := p.peek()
	message := "unexpected '" + t.Spelling + "'"
	if t.Kind == "END" {
		message = "unexpected end of program"
	}
	panic(&CompileError{"syntax", message, t.Position})
}
func (p *Parser) take(kind string) Token {
	if p.peek().Kind != kind {
		p.fail()
	}
	t := p.peek()
	p.Index++
	return t
}
func (p *Parser) accept(kind string) bool {
	if p.peek().Kind != kind {
		return false
	}
	p.Index++
	return true
}
func isType(t Token) bool { return wordIn("int bool void", t.Kind) }
func (p *Parser) declarationStart() *Declaration {
	if !isType(p.peek()) {
		p.fail()
	}
	typ := p.peek().Kind
	p.Index++
	return &Declaration{Type: typ, Name: p.take("identifier")}
}
func (p *Parser) program() *Program {
	out := &Program{}
	for p.peek().Kind != "END" {
		d := p.declarationStart()
		if p.accept("(") {
			d.Function = true
			if !p.accept(")") {
				d.Parameters = append(d.Parameters, p.declarationStart())
				for p.accept(",") {
					d.Parameters = append(d.Parameters, p.declarationStart())
				}
				p.take(")")
			}
			d.Body = p.block()
			out.Functions = append(out.Functions, d)
		} else {
			if p.accept("[") {
				d.Array = true
				d.Size = p.take("integer")
				p.take("]")
			} else if p.accept("=") {
				d.Initializer = p.expression(1)
			}
			p.take(";")
			out.Globals = append(out.Globals, d)
		}
		out.Declarations = append(out.Declarations, d)
	}
	out.End = p.peek()
	return out
}
func (p *Parser) block() *Statement {
	s := &Statement{Kind: "block", Token: p.take("{")}
	for p.peek().Kind != "}" {
		if p.peek().Kind == "END" {
			p.fail()
		}
		if isType(p.peek()) {
			start := p.peek()
			d := p.declarationStart()
			if p.accept("=") {
				d.Initializer = p.expression(1)
			}
			p.take(";")
			s.Statements = append(s.Statements, &Statement{Kind: "declaration", Token: start, Declaration: d})
		} else {
			s.Statements = append(s.Statements, p.statement())
		}
	}
	s.Close = p.take("}")
	return s
}
func (p *Parser) statement() *Statement {
	t := p.peek()
	if t.Kind == "{" {
		return p.block()
	}
	p.Index++
	s := &Statement{Kind: t.Kind, Token: t}
	switch t.Kind {
	case "if":
		p.take("(")
		s.Condition = p.expression(1)
		p.take(")")
		s.Then = p.statement()
		if p.accept("else") {
			s.Else = p.statement()
		}
	case "while":
		p.take("(")
		s.Condition = p.expression(1)
		p.take(")")
		s.Body = p.statement()
	case "for":
		p.take("(")
		if isType(p.peek()) {
			start := p.peek()
			d := p.declarationStart()
			p.take("=")
			d.Initializer = p.expression(1)
			s.Init = &Statement{Kind: "declaration", Token: start, Declaration: d}
		} else if p.peek().Kind != ";" {
			s.Init = p.simple()
		}
		p.take(";")
		if p.peek().Kind != ";" {
			s.Condition = p.expression(1)
		}
		p.take(";")
		if p.peek().Kind != ")" {
			s.Update = p.simple()
		}
		p.take(")")
		s.Body = p.statement()
	case "break", "continue":
		p.take(";")
	case "return":
		if p.peek().Kind != ";" {
			s.Expr = p.expression(1)
		}
		p.take(";")
	case "print":
		p.take("(")
		s.Expressions = append(s.Expressions, p.expression(1))
		for p.accept(",") {
			s.Expressions = append(s.Expressions, p.expression(1))
		}
		p.take(")")
		p.take(";")
	case "identifier", "read":
		p.Index--
		s = p.simple()
		p.take(";")
	default:
		p.Index--
		p.fail()
	}
	return s
}
func (p *Parser) call(t Token) *Expr {
	p.take("(")
	arguments := []*Expr{}
	if !p.accept(")") {
		arguments = append(arguments, p.expression(1))
		for p.accept(",") {
			arguments = append(arguments, p.expression(1))
		}
		p.take(")")
	}
	return &Expr{Kind: "call", Token: t, Children: arguments}
}
func (p *Parser) simple() *Statement {
	t := p.peek()
	if t.Kind == "read" {
		p.Index++
		p.take("(")
		p.take(")")
		return &Statement{Kind: "call", Token: t, Expr: &Expr{Kind: "read", Token: t}}
	}
	t = p.take("identifier")
	if p.peek().Kind == "(" {
		return &Statement{Kind: "call", Token: t, Expr: p.call(t)}
	}
	s := &Statement{Kind: "assignment", Token: t}
	if p.accept("[") {
		s.Index = p.expression(1)
		p.take("]")
	}
	p.take("=")
	s.Expr = p.expression(1)
	return s
}
func precedence(op string) int {
	switch op {
	case "||":
		return 1
	case "&&":
		return 2
	case "==", "!=":
		return 3
	case "<", "<=", ">", ">=":
		return 4
	case "+", "-":
		return 5
	case "*", "/", "%":
		return 6
	}
	return 0
}
func (p *Parser) expression(minimum int) *Expr {
	left := p.unary()
	for {
		level := precedence(p.peek().Kind)
		if level == 0 || level < minimum {
			break
		}
		op := p.peek()
		p.Index++
		right := p.expression(level + 1)
		left = &Expr{Kind: "binary", Token: op, Children: []*Expr{left, right}}
	}
	return left
}
func (p *Parser) unary() *Expr {
	if p.peek().Kind == "-" || p.peek().Kind == "!" {
		op := p.peek()
		p.Index++
		return &Expr{Kind: "unary", Token: op, Children: []*Expr{p.unary()}}
	}
	return p.primary()
}
func (p *Parser) primary() *Expr {
	t := p.peek()
	switch t.Kind {
	case "integer":
		p.Index++
		return &Expr{Kind: "integer", Token: t, Value: t.Integer}
	case "true", "false":
		p.Index++
		value := int64(0)
		if t.Kind == "true" {
			value = 1
		}
		return &Expr{Kind: "boolean", Token: t, Value: value}
	case "read":
		p.Index++
		p.take("(")
		p.take(")")
		return &Expr{Kind: "read", Token: t}
	case "(":
		p.Index++
		e := p.expression(1)
		p.take(")")
		return e
	case "identifier":
		p.Index++
		if p.peek().Kind == "(" {
			return p.call(t)
		}
		if p.accept("[") {
			index := p.expression(1)
			p.take("]")
			return &Expr{Kind: "array", Token: t, Children: []*Expr{index}}
		}
		return &Expr{Kind: "variable", Token: t}
	}
	p.fail()
	return nil
}
func parse(tokens []Token) (program *Program, err *CompileError) {
	defer func() {
		if value := recover(); value != nil {
			if failure, ok := value.(*CompileError); ok {
				err = failure
			} else {
				panic(value)
			}
		}
	}()
	p := Parser{Tokens: tokens}
	program = p.program()
	return
}

package main

import "fmt"

type Symbol struct {
	Name, Type, Kind    string
	Declaration         *Declaration
	Array               bool
	Size, Address, Slot int
	References          []Position
	Reads               int
	Calls               map[*Symbol]bool
}
type Semantics struct {
	Program  *Program
	Scopes   []map[string]*Symbol
	Function *Declaration
	Loops    int
}

func semanticError(pos Position, message string) { panic(&CompileError{"semantic", message, pos}) }
func (s *Semantics) symbol(d *Declaration, kind string) *Symbol {
	symbol := &Symbol{Name: d.Name.Spelling, Type: d.Type, Kind: kind, Declaration: d, Array: d.Array, Size: int(d.Size.Integer), Calls: map[*Symbol]bool{}}
	d.Symbol = symbol
	s.Program.Symbols = append(s.Program.Symbols, symbol)
	return symbol
}
func (s *Semantics) lookup(t Token, read bool) *Symbol {
	var symbol *Symbol
	for i := len(s.Scopes) - 1; i >= 0; i-- {
		if value, found := s.Scopes[i][t.Spelling]; found {
			symbol = value
			break
		}
	}
	if symbol == nil {
		symbol = s.Program.Names[t.Spelling]
	}
	if symbol != nil {
		symbol.References = append(symbol.References, t.Position)
		if read {
			symbol.Reads++
		}
	}
	return symbol
}
func (s *Semantics) variable(t Token, array, read bool) *Symbol {
	symbol := s.lookup(t, read)
	name := t.Spelling
	if symbol == nil {
		semanticError(t.Position, "undeclared identifier '"+name+"'")
	}
	if symbol.Kind == "function" {
		semanticError(t.Position, "'"+name+"' is a function, not a variable")
	}
	if array && !symbol.Array {
		semanticError(t.Position, "'"+name+"' is not an array")
	}
	if !array && symbol.Array {
		semanticError(t.Position, "array '"+name+"' used without index")
	}
	return symbol
}
func (s *Semantics) expression(e *Expr, statement bool) string {
	typ := ""
	name := e.Token.Spelling
	pos := e.position()
	switch e.Kind {
	case "integer", "read":
		typ = "int"
	case "boolean":
		typ = "bool"
	case "variable":
		e.Referent = s.variable(e.Token, false, true)
		typ = e.Referent.Type
	case "array":
		e.Referent = s.variable(e.Token, true, true)
		if s.expression(e.Children[0], false) != "int" {
			semanticError(pos, "index of '"+name+"' must be int")
		}
		typ = "int"
	case "call":
		symbol := s.lookup(e.Token, true)
		if symbol == nil {
			semanticError(pos, "undeclared function '"+name+"'")
		}
		if symbol.Kind != "function" {
			semanticError(pos, "'"+name+"' is not a function")
		}
		e.Referent = symbol
		if s.Function != nil {
			s.Function.Symbol.Calls[symbol] = true
		}
		parameters := symbol.Declaration.Parameters
		if len(e.Children) != len(parameters) {
			semanticError(pos, fmt.Sprintf("wrong number of arguments to '%s' (expected %d, found %d)", name, len(parameters), len(e.Children)))
		}
		for j, argument := range e.Children {
			if s.expression(argument, false) != parameters[j].Type {
				semanticError(pos, fmt.Sprintf("argument %d of '%s' must be %s", j+1, name, parameters[j].Type))
			}
		}
		if !statement && symbol.Type == "void" {
			semanticError(pos, "void function '"+name+"' used as a value")
		}
		typ = symbol.Type
	case "unary":
		operand := s.expression(e.Children[0], false)
		required := "int"
		if e.Token.Spelling == "!" {
			required = "bool"
		}
		if operand != required {
			semanticError(pos, "operator '"+e.Token.Spelling+"' requires "+required+" operand")
		}
		typ = operand
	case "binary":
		left := s.expression(e.Children[0], false)
		right := s.expression(e.Children[1], false)
		op := e.Token.Spelling
		switch {
		case wordIn("+ - * / % < <= > >=", op):
			if left != "int" || right != "int" {
				semanticError(pos, "operator '"+op+"' requires int operands")
			}
			typ = "int"
			if wordIn("< <= > >=", op) {
				typ = "bool"
			}
		case op == "==" || op == "!=":
			if left != right {
				semanticError(pos, "operator '"+op+"' requires operands of the same type")
			}
			typ = "bool"
		default:
			if left != "bool" || right != "bool" {
				semanticError(pos, "operator '"+op+"' requires bool operands")
			}
			typ = "bool"
		}
	}
	e.Type = typ
	return typ
}
func canComplete(s *Statement) bool {
	switch s.Kind {
	case "return", "break", "continue":
		return false
	case "block":
		for _, child := range s.Statements {
			if !canComplete(child) {
				return false
			}
		}
		return true
	case "if":
		return s.Else == nil || canComplete(s.Then) || canComplete(s.Else)
	}
	return true
}
func (s *Semantics) declaration(d *Declaration) {
	name := d.Name.Spelling
	pos := d.Name.Position
	current := s.Scopes[len(s.Scopes)-1]
	if d.Type == "void" {
		semanticError(pos, "variable '"+name+"' cannot have type void")
	}
	if _, found := current[name]; found {
		semanticError(pos, "redeclaration of '"+name+"'")
	}
	if d.Initializer != nil && s.expression(d.Initializer, false) != d.Type {
		semanticError(pos, "type mismatch in initialization of '"+name+"'")
	}
	current[name] = s.symbol(d, "local")
}
func (s *Semantics) statement(n *Statement) {
	pos := n.Token.Position
	switch n.Kind {
	case "declaration":
		s.declaration(n.Declaration)
	case "assignment":
		name := n.Token.Spelling
		n.Referent = s.variable(n.Token, n.Index != nil, false)
		if n.Index != nil && s.expression(n.Index, false) != "int" {
			semanticError(pos, "index of '"+name+"' must be int")
		}
		if s.expression(n.Expr, false) != n.Referent.Type {
			semanticError(pos, "type mismatch in assignment to '"+name+"'")
		}
	case "call":
		s.expression(n.Expr, true)
	case "if", "while":
		if s.expression(n.Condition, false) != "bool" {
			semanticError(pos, "condition of '"+n.Kind+"' must be bool")
		}
		if n.Kind == "if" {
			s.statement(n.Then)
			if n.Else != nil {
				s.statement(n.Else)
			}
		} else {
			s.Loops++
			s.statement(n.Body)
			s.Loops--
		}
	case "for":
		s.Scopes = append(s.Scopes, map[string]*Symbol{})
		if n.Init != nil {
			s.statement(n.Init)
		}
		if n.Condition != nil && s.expression(n.Condition, false) != "bool" {
			semanticError(pos, "condition of 'for' must be bool")
		}
		if n.Update != nil {
			s.statement(n.Update)
		}
		s.Loops++
		s.statement(n.Body)
		s.Loops--
		s.Scopes = s.Scopes[:len(s.Scopes)-1]
	case "break", "continue":
		if s.Loops == 0 {
			semanticError(pos, "'"+n.Kind+"' outside loop")
		}
	case "return":
		function := s.Function
		if function.Type == "void" {
			if n.Expr != nil {
				semanticError(pos, "function '"+function.Name.Spelling+"' must not return a value")
			}
		} else {
			if n.Expr == nil {
				semanticError(pos, "function '"+function.Name.Spelling+"' must return a value")
			}
			if s.expression(n.Expr, false) != function.Type {
				semanticError(pos, "return value of '"+function.Name.Spelling+"' must be "+function.Type)
			}
		}
	case "print":
		for j, e := range n.Expressions {
			if s.expression(e, false) != "int" {
				semanticError(pos, fmt.Sprintf("argument %d of 'print' must be int", j+1))
			}
		}
	case "block":
		s.Scopes = append(s.Scopes, map[string]*Symbol{})
		for _, child := range n.Statements {
			s.statement(child)
		}
		s.Scopes = s.Scopes[:len(s.Scopes)-1]
	}
}
func analyze(program *Program) (err *CompileError) {
	defer func() {
		if value := recover(); value != nil {
			if failure, ok := value.(*CompileError); ok {
				err = failure
			} else {
				panic(value)
			}
		}
	}()
	program.Names = map[string]*Symbol{}
	s := &Semantics{Program: program}
	for _, d := range program.Declarations {
		name := d.Name.Spelling
		pos := d.Name.Position
		if !d.Function {
			if d.Array {
				if d.Type != "int" {
					semanticError(pos, "array '"+name+"' must have element type int")
				}
				if d.Size.Integer == 0 {
					semanticError(d.Size.Position, "array '"+name+"' must have a positive size")
				}
			} else if d.Type == "void" {
				semanticError(pos, "variable '"+name+"' cannot have type void")
			}
		}
		if program.Names[name] != nil {
			semanticError(pos, "redeclaration of '"+name+"'")
		}
		if d.Function {
			seen := map[string]bool{}
			for _, parameter := range d.Parameters {
				pname := parameter.Name.Spelling
				if parameter.Type == "void" {
					semanticError(parameter.Name.Position, "parameter '"+pname+"' cannot have type void")
				}
				if seen[pname] {
					semanticError(parameter.Name.Position, "redeclaration of '"+pname+"'")
				}
				seen[pname] = true
			}
			program.Names[name] = s.symbol(d, "function")
		} else {
			if d.Initializer != nil {
				var first *Expr
				var visit func(*Expr)
				visit = func(e *Expr) {
					if wordIn("variable array call read", e.Kind) && (first == nil || earlier(e.position(), first.position())) {
						first = e
					}
					for _, child := range e.Children {
						visit(child)
					}
				}
				visit(d.Initializer)
				if first != nil {
					semanticError(first.position(), "global initializer must be constant")
				}
				if s.expression(d.Initializer, false) != d.Type {
					semanticError(pos, "type mismatch in initialization of '"+name+"'")
				}
			}
			program.Names[name] = s.symbol(d, "global")
		}
	}
	main := program.Names["main"]
	if main == nil || main.Kind != "function" {
		semanticError(program.End.Position, "no main function")
	}
	if main.Type != "void" || len(main.Declaration.Parameters) != 0 {
		semanticError(main.Declaration.Name.Position, "main must be declared as 'void main()'")
	}
	for _, function := range program.Functions {
		s.Function = function
		s.Scopes = []map[string]*Symbol{{}}
		for _, parameter := range function.Parameters {
			s.Scopes[0][parameter.Name.Spelling] = s.symbol(parameter, "parameter")
		}
		for _, statement := range function.Body.Statements {
			s.statement(statement)
		}
		if function.Type != "void" && canComplete(function.Body) {
			semanticError(function.Name.Position, "missing return in function '"+function.Name.Spelling+"'")
		}
	}
	return nil
}

package main

import (
	"fmt"
	"strconv"
	"strings"
)

type ExecutableInstruction struct {
	Instruction
	Unit *Unit
}
type Frame struct {
	Locals []int64
	Return int
}
type RunResult struct {
	Output                               []string
	Executed, MaximumStack, MaximumDepth int
	Counts                               []int
	Calls                                map[string]int
	Pairs                                map[[2]string]int
	Error                                string
	FaultPC                              int
	Frames                               []Frame
}

func flatten(units []*Unit) []ExecutableInstruction {
	out := []ExecutableInstruction{}
	for _, unit := range units {
		for _, original := range unit.Code {
			instruction := original
			if jump(instruction.Op) {
				instruction.A += int64(unit.Start)
			}
			out = append(out, ExecutableInstruction{instruction, unit})
		}
	}
	return out
}
func execute(units []*Unit, cells int, input []int64) *RunResult {
	code := flatten(units)
	r := &RunResult{Counts: make([]int, len(code)), Calls: map[string]int{}, Pairs: map[[2]string]int{}, FaultPC: -1}
	globals := make([]int64, cells)
	stack := []int64{}
	frames := []Frame{}
	pc, read := 0, 0
	starts := map[int]*Unit{}
	for _, unit := range units {
		starts[unit.Start] = unit
	}
	pop := func() int64 {
		value := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		return value
	}
	fault := func(message string) *RunResult {
		r.Error = message
		r.FaultPC = pc
		r.Frames = append([]Frame{}, frames...)
		return r
	}
	for {
		instruction := code[pc]
		if r.Executed == 100000 {
			return fault("instruction limit exceeded")
		}
		r.Executed++
		r.Counts[pc]++
		next := pc + 1
		switch instruction.Op {
		case "PUSH":
			stack = append(stack, instruction.A)
		case "POP":
			pop()
		case "LOADG":
			stack = append(stack, globals[int(instruction.A)])
		case "STOREG":
			globals[int(instruction.A)] = pop()
		case "LOADL":
			stack = append(stack, frames[len(frames)-1].Locals[int(instruction.A)])
		case "STOREL":
			frames[len(frames)-1].Locals[int(instruction.A)] = pop()
		case "LOADA", "STOREA":
			value := int64(0)
			if instruction.Op == "STOREA" {
				value = pop()
			}
			index := pop()
			if index < 0 || index >= instruction.B {
				return fault(fmt.Sprintf("index %d out of bounds for array of size %d", index, instruction.B))
			}
			address := int(instruction.A + index)
			if instruction.Op == "LOADA" {
				stack = append(stack, globals[address])
			} else {
				globals[address] = value
			}
		case "ADD", "SUB", "MUL", "DIV", "MOD":
			b, a := pop(), pop()
			value := int64(0)
			switch instruction.Op {
			case "ADD":
				value = a + b
			case "SUB":
				value = a - b
			case "MUL":
				value = a * b
			case "DIV", "MOD":
				if b == 0 {
					return fault("division by zero")
				}
				quotient := a / b
				if instruction.Op == "DIV" {
					value = quotient
				} else {
					value = a - quotient*b
				}
			}
			if value < -2147483648 || value > 2147483647 {
				return fault("integer overflow")
			}
			stack = append(stack, value)
		case "NEG":
			value := -pop()
			if value < -2147483648 || value > 2147483647 {
				return fault("integer overflow")
			}
			stack = append(stack, value)
		case "NOT":
			value := pop()
			result := int64(0)
			if value == 0 {
				result = 1
			}
			stack = append(stack, result)
		case "LT", "LE", "GT", "GE", "EQ", "NE":
			b, a := pop(), pop()
			answer := false
			switch instruction.Op {
			case "LT":
				answer = a < b
			case "LE":
				answer = a <= b
			case "GT":
				answer = a > b
			case "GE":
				answer = a >= b
			case "EQ":
				answer = a == b
			case "NE":
				answer = a != b
			}
			value := int64(0)
			if answer {
				value = 1
			}
			stack = append(stack, value)
		case "JUMP":
			next = int(instruction.A)
		case "JUMPF", "JUMPT":
			value := pop()
			if instruction.Op == "JUMPF" && value == 0 || instruction.Op == "JUMPT" && value != 0 {
				next = int(instruction.A)
			}
		case "CALL":
			if len(frames) == 100 {
				return fault("call depth limit exceeded")
			}
			count := int(instruction.B)
			locals := append([]int64{}, stack[len(stack)-count:]...)
			stack = stack[:len(stack)-count]
			frames = append(frames, Frame{locals, pc + 1})
			next = int(instruction.A)
			called := starts[next].Name
			r.Calls[called]++
			r.Pairs[[2]string{instruction.Unit.Name, called}]++
		case "ENTER":
			frame := &frames[len(frames)-1]
			for len(frame.Locals) < int(instruction.A) {
				frame.Locals = append(frame.Locals, 0)
			}
		case "RET", "RETV":
			next = frames[len(frames)-1].Return
			frames = frames[:len(frames)-1]
		case "READ":
			if read == len(input) {
				return fault("read past end of input")
			}
			stack = append(stack, input[read])
			read++
		case "PRINT":
			count := int(instruction.A)
			values := []string{}
			for _, value := range stack[len(stack)-count:] {
				values = append(values, strconv.FormatInt(value, 10))
			}
			stack = stack[:len(stack)-count]
			r.Output = append(r.Output, strings.Join(values, " "))
		case "HALT":
			r.MaximumStack = max(r.MaximumStack, len(stack))
			r.MaximumDepth = max(r.MaximumDepth, len(frames))
			return r
		}
		r.MaximumStack = max(r.MaximumStack, len(stack))
		r.MaximumDepth = max(r.MaximumDepth, len(frames))
		pc = next
	}
}
